#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=1L)stop("Provide project.yaml",call.=FALSE)
all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/");app_env<-new.env(parent=.GlobalEnv);source(file.path(root,"app/shiny/app.R"),local=app_env)
shiny::testServer(app_env$server,{config<-normalizePath(args[[1]],winslash="/");session$setInputs(project_selector=config,open_project=1);session$flushReact();included<-included_samples();stopifnot(length(included)==8L,setequal(preprocessing_selected_samples(),included));status<-sample_pipeline_status();for(stage in c("mapping","create_hit_file","summary")){resolved<-app_env$resolve_selected_preprocessing_samples(preprocessing_selected_samples(),active()$samples,status,stage);stopifnot(setequal(resolved$requested,included))};chosen<-included[1:2];preprocessing_selected_samples(chosen);session$flushReact();stopifnot(identical(preprocessing_selected_samples(),chosen));for(stage in c("mapping","create_hit_file","summary"))stopifnot(identical(app_env$resolve_selected_preprocessing_samples(preprocessing_selected_samples(),active()$samples,status,stage)$requested,chosen));go_to("preprocessing","preprocessing_tabs","mapping");go_to("preprocessing","preprocessing_tabs","hit_files");go_to("preprocessing","preprocessing_tabs","summary_tables");go_to("preprocessing","preprocessing_tabs","samples");session$flushReact();stopifnot(identical(preprocessing_selected_samples(),chosen),jobs$job_is_running()==FALSE)})
cat("PASS\n")
